public String kangaroo(int x1, int v1, int x2, int v2) {
    if (v1 <= v2) {                  // back kangaroo can never catch up
        return x1 == x2 ? "YES" : "NO";
    }
    while (x1 < x2) {                 // close the gap one jump at a time
        x1 += v1;
        x2 += v2;
    }
    return x1 == x2 ? "YES" : "NO";   // landed together exactly, or overshot
}

public String kangaroo(int x1, int v1, int x2, int v2) {
    if (v1 == v2) {                      // denominator would be zero
        return x1 == x2 ? "YES" : "NO";
    }
    int dx = x1 - x2;
    int dv = v2 - v1;
    boolean meets = dx % dv == 0 && dx / dv >= 0;
    return meets ? "YES" : "NO";
}

